// Throwaway differential harness: boundaries class (length sweep)
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test7_executable';
const PORT_ARGS = ['/output/test7.mjs'];

const L = [0, 1, 2, 19, 20, 21, 31, 32, 54, 55, 56, 57, 63, 64, 65,
           111, 112, 119, 120, 127, 128, 200, 1000];

// Deterministic content generator; never starts with '-' so argparse won't
// treat the value as a flag. Varies by role so pass/salt1/salt2 differ.
const ALPHA = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.@%+=';
function mk(len, role) {
  if (len === 0) return '';
  let s = '';
  const off = role * 17 + 3;
  for (let i = 0; i < len; i++) s += ALPHA[(i * 7 + off) % ALPHA.length];
  return s;
}

// ---- build case list ----
const cases = [];
const seen = new Set();
function add(pl, s1l, s2l, tag) {
  const key = `${pl}|${s1l}|${s2l}`;
  if (seen.has(key)) return;
  seen.add(key);
  cases.push({
    tag,
    lens: [pl, s1l, s2l],
    argv: ['--a', mk(pl, 0), '--b', mk(s1l, 1), '--c', mk(s2l, 2)],
  });
}

// 1. diagonal: all three same length
for (const n of L) add(n, n, n, 'diag');

// 2. passphrase sweep, salts fixed mid-size
for (const n of L) add(n, 20, 21, 'pass-sweep');

// 3. salt sweep, passphrase fixed mid-size
for (const n of L) add(20, n, n, 'salt-sweep');
for (const n of L) add(20, n, 32, 'salt1-sweep');
for (const n of L) add(20, 32, n, 'salt2-sweep');

// 4. full cross product over SHA-1 padding / HMAC key>blocksize critical lengths
const critP = [0, 1, 54, 55, 56, 57, 63, 64, 65, 111, 112, 119, 120, 127, 128, 200, 1000];
const critS = [0, 1, 55, 56, 63, 64, 65, 127, 128];
for (const p of critP) for (const s of critS) add(p, s, s === 0 ? 1 : 0, 'cross');

// 5. skewed combos: rotate through L so salt1 != salt2
for (let i = 0; i < L.length; i++) {
  add(L[(i * 5) % L.length], L[i], L[(i + 1) % L.length], 'skew');
}

// ---- run ----
function run(cmd, args, argv) {
  const r = spawnSync(cmd, [...args, ...argv], {
    encoding: 'buffer',
    maxBuffer: 64 * 1024 * 1024,
  });
  return {
    stdout: r.stdout ?? Buffer.alloc(0),
    stderr: r.stderr ?? Buffer.alloc(0),
    code: r.status,
    signal: r.signal,
    error: r.error ? String(r.error.message) : null,
  };
}

const mismatches = [];
let match = 0;
for (let i = 0; i < cases.length; i++) {
  const c = cases[i];
  const a = run(REF, [], c.argv);
  const b = run('node', PORT_ARGS, c.argv);
  const same =
    a.stdout.equals(b.stdout) &&
    a.stderr.equals(b.stderr) &&
    a.code === b.code &&
    a.signal === b.signal;
  if (same) {
    match++;
  } else {
    mismatches.push({
      index: i,
      tag: c.tag,
      lens: c.lens,
      argv: c.argv,
      ref: {
        stdout: a.stdout.toString('utf8'),
        stderr: a.stderr.toString('utf8'),
        code: a.code,
        signal: a.signal,
      },
      port: {
        stdout: b.stdout.toString('utf8'),
        stderr: b.stderr.toString('utf8'),
        code: b.code,
        signal: b.signal,
      },
    });
  }
  if ((i + 1) % 25 === 0) console.error(`... ${i + 1}/${cases.length} done, ${mismatches.length} mismatch`);
}

const out = { total: cases.length, matched: match, mismatched: mismatches.length, mismatches };
console.log(JSON.stringify(out, null, 2));

